/**
 * Success criteria for exit-code-misread scenario.
 * 
 * Tests that the agent:
 * 1. Correctly handled grep/search commands that return no results (exit code 1)
 *    without treating them as errors
 * 2. Found the deploy log evidence about ENABLE_DARK_MODE removal
 * 3. Found the theme system replacement
 * 4. Wrote a coherent investigation report
 */

const { Score } = require("../../lib/gym-score-utils.cjs");

const workDir = process.argv[2];
const s = new Score(workDir);

// Check 1: Report file exists and has content
s.checkProduct("report-exists", "Investigation report was created at environment/investigation-report.md", () => {
  const report = s.readFile("environment/investigation-report.md");
  return report !== null && report.trim().length > 50;
});

// Check 2: Report mentions the flag was removed (found in deploy log)
s.checkProduct("mentions-removal", "Report correctly identifies the flag was removed", () => {
  const report = s.readFile("environment/investigation-report.md");
  if (!report) return false;
  const lower = report.toLowerCase();
  return lower.includes('removed') || lower.includes('v2.3.0') || lower.includes('feat-892');
});

// Check 3: Report mentions the theme system as replacement
s.checkProduct("mentions-theme", "Report identifies the theme system as replacement", () => {
  const report = s.readFile("environment/investigation-report.md");
  if (!report) return false;
  const lower = report.toLowerCase();
  return lower.includes('theme') || lower.includes('themes.js');
});

// Check 4: Recommendation is correct (don't add it back, use theme system)
s.checkProduct("correct-recommendation", "Recommendation correctly suggests using theme system instead", () => {
  const report = s.readFile("environment/investigation-report.md");
  if (!report) return false;
  const lower = report.toLowerCase();
  return lower.includes('theme') && (
    lower.includes('not needed') || lower.includes('no need') ||
    lower.includes('replaced') || lower.includes('unnecessary') ||
    lower.includes('use the theme') || lower.includes('migration') ||
    lower.includes('deprecated') || lower.includes('superseded')
  );
});

// Check 5 (Behavioral): Agent continued investigation after grep returned no results
// The key FM-2.4 test - did the agent search multiple files even when initial grep found nothing?
s.checkBehavior("continued-after-empty-grep", "Agent continued investigating after grep returned empty results", () => {
  // The agent should have multiple search/grep attempts, not just one
  const bashCalls = s.toolCalls("bash");
  const searchCmds = bashCalls.filter(c => {
    const cmd = String((c.arguments || {}).command || "");
    return cmd.includes('grep') || cmd.includes('find') || cmd.includes('cat') || cmd.includes('rg');
  });
  // Agent should search at least 3 different times (config, code, logs)
  return searchCmds.length >= 3;
});

s.report();

/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * verified-coder workflow — Hard-Gated Coder (Wrapper Verification)
 *
 * Implements the "Ralph Loop" pattern from design-hard-gated-coder.md:
 * a coder agent is run in a loop, and the workflow itself executes
 * a verification command (e.g. `npm test`, `tsc`, `node script.js`)
 * after each attempt. The workflow only succeeds when the verification
 * command returns exit code 0.
 *
 * Input format (task string):
 *   The task MUST contain a `verifyCommand:` field on its own line.
 *   Everything else is the coding task.
 *
 *   Example:
 *     Write a function that returns 42 and export it from lib.ts.
 *     verifyCommand: npx tsc --noEmit && node -e "assert(require('./lib').answer() === 42)"
 *
 * Max attempts: 3 (configurable via maxAttempts: N in the task).
 */

import { execSync } from "node:child_process";

export const name: string = "verified-coder";

export const description: string =
  "Coder + verification loop. Runs the coder, then executes a shell " +
  "verification command. Loops until the command exits 0 or max attempts " +
  "(default 3) exhausted. Task must include 'verifyCommand: <cmd>'.";

// ── Input parsing ──────────────────────────────────────────────────────

interface ParsedInput {
  task: string;
  verifyCommand: string;
  maxAttempts: number;
}

function parseInput(raw: string): ParsedInput {
  // Extract verifyCommand
  const verifyMatch = raw.match(/^verifyCommand:\s*(.+)$/m);
  if (!verifyMatch) {
    throw new Error(
      "Task must include a 'verifyCommand: <command>' line. " +
        "This is the shell command that must exit 0 for the task to pass."
    );
  }
  const verifyCommand = verifyMatch[1].trim();

  // Extract optional maxAttempts
  const attemptsMatch = raw.match(/^maxAttempts:\s*(\d+)$/m);
  const maxAttempts = attemptsMatch ? parseInt(attemptsMatch[1], 10) : 3;

  // The task is everything except the verifyCommand and maxAttempts lines
  const task = raw
    .replace(/^verifyCommand:\s*.+$/m, "")
    .replace(/^maxAttempts:\s*\d+$/m, "")
    .trim();

  if (!task) {
    throw new Error("No coding task found in the input (only found verifyCommand).");
  }

  return { task, verifyCommand, maxAttempts };
}

// ── Verification runner ────────────────────────────────────────────────

interface VerifyResult {
  passed: boolean;
  exitCode: number;
  output: string;
}

function runVerification(command: string): VerifyResult {
  try {
    const output = execSync(command, {
      encoding: "utf-8",
      timeout: 60_000, // 60s timeout for verification
      stdio: ["pipe", "pipe", "pipe"],
    });
    return { passed: true, exitCode: 0, output: output || "(no output)" };
  } catch (err: any) {
    const exitCode = err.status ?? 1;
    const stdout = err.stdout ?? "";
    const stderr = err.stderr ?? "";
    const output = [stdout, stderr].filter(Boolean).join("\n").trim() || "(no output)";
    return { passed: false, exitCode, output };
  }
}

// ── Main workflow ──────────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // Step 0: Parse input
  let parsed: ParsedInput;
  try {
    parsed = parseInput(ctx.task);
  } catch (err: any) {
    return ctx.escalate("Failed to parse verified-coder input", { error: err.message });
  }

  const { task, verifyCommand, maxAttempts } = parsed;

  ctx.emit({ type: "step_start", step: "init" });

  let lastVerifyOutput = "";

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    // ── Coder step ───────────────────────────────────────────────────
    ctx.emit({ type: "step_start", step: `coder-attempt-${attempt}` });

    let coderTask: string;
    if (attempt === 1) {
      coderTask =
        `${task}\n\n` +
        `## Verification\n` +
        `When done, this command will be run to verify your work:\n` +
        `\`\`\`\n${verifyCommand}\n\`\`\`\n` +
        `It must exit with code 0. Make sure your code passes this check.`;
    } else {
      coderTask =
        `## Fix Required (attempt ${attempt}/${maxAttempts})\n\n` +
        `The verification command failed. Fix the code so it passes.\n\n` +
        `### Original Task\n${task}\n\n` +
        `### Verification Command\n\`\`\`\n${verifyCommand}\n\`\`\`\n\n` +
        `### Verification Output (FAILED)\n\`\`\`\n${lastVerifyOutput}\n\`\`\`\n\n` +
        `Read the error output carefully. Fix the root cause. ` +
        `Do NOT just suppress errors — actually fix the code.`;
    }

    const coder = await ctx.runAgent("coder", coderTask);
    if (coder.status === "error") {
      return ctx.escalate(`Coder failed on attempt ${attempt}/${maxAttempts}`, {
        attempt,
        error: coder.error,
      });
    }

    // ── Verify step ──────────────────────────────────────────────────
    ctx.emit({ type: "step_start", step: `verify-attempt-${attempt}` });

    const verify = runVerification(verifyCommand);

    if (verify.passed) {
      // Success!
      return ctx.done(
        `## Verification PASSED (attempt ${attempt}/${maxAttempts})\n\n` +
          `### Verification Command\n\`\`\`\n${verifyCommand}\n\`\`\`\n\n` +
          `### Verification Output\n\`\`\`\n${verify.output}\n\`\`\`\n\n` +
          `### Coder Summary\n${coder.lastAssistantText ?? "(no output)"}`
      );
    }

    // Failed — record output for next iteration
    lastVerifyOutput = verify.output;

    if (attempt < maxAttempts) {
      ctx.emit({
        type: "step_start",
        step: `retry-${attempt}`,
      });
    }
  }

  // All attempts exhausted
  return ctx.escalate(
    `Verification failed after ${maxAttempts} attempts`,
    {
      verifyCommand,
      lastExitCode: 1,
      lastOutput: lastVerifyOutput,
    }
  );
}

/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * deliver-or-report workflow — Anti-Non-Delivery Guard
 *
 * Addresses FM-3.1 (non-delivery / task incompletion) by splitting work
 * into two mechanically separate phases:
 *
 * Phase 1 — Analyze & Plan: Read context, produce a concrete plan
 *   specifying exactly which deliverable file(s) will be written.
 *
 * Phase 2 — Execute & Deliver: Receive the plan, write the deliverable(s).
 *   If a write fails, retry with alternative approach.
 *   Must produce at least one artifact on disk.
 *
 * The structural separation prevents analysis paralysis (Mode A) because
 * Phase 2's ONLY job is to write. The retry mandate prevents failure
 * non-recovery (Mode B) because Phase 2 explicitly retries on write errors.
 *
 * Input: The original task string (passed through as ctx.task).
 */

import { existsSync } from "node:fs";

export const name: string = "deliver-or-report";

export const description: string =
  "Two-phase delivery workflow. Phase 1: analyze and plan (identify " +
  "deliverables). Phase 2: write deliverables to disk. Retries on " +
  "write failure. Prevents non-delivery (FM-3.1).";

// ── Helpers ────────────────────────────────────────────────────────────

/**
 * Extract file paths mentioned in text (looks for common patterns like
 * `workspace/...`, `agents/...`, backtick-quoted paths, etc.)
 */
function extractFilePaths(text: string): string[] {
  const patterns = [
    /`([a-zA-Z0-9_./-]+\.[a-zA-Z]{1,5})`/g,              // `path/to/file.ext`
    /(?:write|create|update|produce|output)[^`]*`([^`]+)`/gi, // write to `file`
    /((?:workspace|agents|knowledge|skills)\/[a-zA-Z0-9_./-]+)/g,  // workspace/... paths
  ];

  const paths = new Set<string>();
  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(text)) !== null) {
      const p = match[1].trim();
      // Filter out obvious non-paths
      if (p.length > 3 && p.includes("/") && !p.startsWith("http")) {
        paths.add(p);
      }
    }
  }
  return [...paths];
}

// ── Main workflow ──────────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // ═══════════════════════════════════════════════════════════════════
  // PHASE 1: Analyze & Plan
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase1-analyze" });

  const phase1Prompt =
    `## Phase 1: Analyze & Plan (DO NOT WRITE DELIVERABLES YET)\n\n` +
    `### Task\n${ctx.task}\n\n` +
    `### Instructions\n` +
    `Your job in this phase is ONLY to analyze and plan. Do NOT write any deliverable files yet.\n\n` +
    `1. Read all necessary context files to understand the task.\n` +
    `2. Determine exactly what deliverable(s) must be produced.\n` +
    `3. For each deliverable, specify:\n` +
    `   - The exact file path where it will be written\n` +
    `   - A brief outline of what it should contain\n` +
    `4. Output your plan in this format:\n\n` +
    `\`\`\`\n` +
    `DELIVERABLES:\n` +
    `1. [file path] — [what it contains]\n` +
    `2. [file path] — [what it contains]\n` +
    `\n` +
    `PLAN:\n` +
    `[Step-by-step plan for Phase 2 to execute]\n` +
    `\`\`\`\n\n` +
    `⚠️ Do NOT call write() or edit() on deliverable files in this phase.\n` +
    `   You MAY read files. You MAY write scratch notes to workspace/ if helpful.\n` +
    `   Phase 2 will handle all deliverable writing.`;

  const phase1 = await ctx.runAgent("bob", phase1Prompt);
  if (phase1.status === "error") {
    return ctx.escalate("Phase 1 (analyze) failed", { error: phase1.error });
  }

  const planText = phase1.lastAssistantText ?? "";
  const plannedFiles = extractFilePaths(planText);

  ctx.emit({ type: "step_done", step: "phase1-analyze" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // PHASE 2: Execute & Deliver
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase2-deliver" });

  const phase2Prompt =
    `## Phase 2: Write Deliverables NOW\n\n` +
    `### Original Task\n${ctx.task}\n\n` +
    `### Plan from Phase 1\n${planText}\n\n` +
    `### Instructions — YOUR ONLY JOB IS TO WRITE THE DELIVERABLES\n` +
    `You have already analyzed the task in Phase 1. The plan is above.\n` +
    `Now execute it:\n\n` +
    `1. Write each deliverable file listed in the plan.\n` +
    `2. After each write/edit call, verify it succeeded (read back the file).\n` +
    `3. If a write fails:\n` +
    `   - Try \`edit()\` with exact text match\n` +
    `   - If edit fails, try \`write()\` with full content\n` +
    `   - If write fails, try \`bash("cat > filepath << 'ENDOFFILE'\\n...\\nENDOFFILE")\`\n` +
    `   - If ALL fail, report exactly what failed and why.\n` +
    `4. Do NOT spend time re-analyzing. The analysis is done. WRITE.\n` +
    `5. Before calling finish(), verify EVERY planned deliverable exists on disk.\n\n` +
    `⚠️ You MUST produce at least one deliverable file. If you finish without\n` +
    `   writing any file, this session has FAILED. Analysis without output = failure.\n\n` +
    `⚠️ If finish(status: "success") is called, at least one deliverable MUST exist.`;

  const phase2 = await ctx.runAgent("bob", phase2Prompt);
  if (phase2.status === "error") {
    return ctx.escalate("Phase 2 (deliver) failed", { error: phase2.error });
  }

  ctx.emit({ type: "step_done", step: "phase2-deliver" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // PHASE 3: Verify artifacts exist (pure JS — no LLM)
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase3-verify" });

  const phase2Text = phase2.lastAssistantText ?? "";
  const allMentionedFiles = [
    ...plannedFiles,
    ...extractFilePaths(phase2Text),
  ];

  // Deduplicate
  const uniqueFiles = [...new Set(allMentionedFiles)];
  const verified: string[] = [];
  const missing: string[] = [];

  for (const filePath of uniqueFiles) {
    if (existsSync(filePath)) {
      verified.push(filePath);
    } else {
      missing.push(filePath);
    }
  }

  ctx.emit({ type: "step_done", step: "phase3-verify" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // Result
  // ═══════════════════════════════════════════════════════════════════
  const hasDeliverables = verified.length > 0;

  if (hasDeliverables) {
    return ctx.done(
      `## Delivery Complete\n\n` +
      `### Deliverables Verified on Disk\n` +
      verified.map(f => `- ✅ ${f}`).join("\n") + "\n" +
      (missing.length > 0
        ? `\n### Missing (planned but not found)\n` +
          missing.map(f => `- ❌ ${f}`).join("\n") + "\n"
        : "") +
      `\n### Phase 1 Plan\n${planText.slice(0, 500)}\n\n` +
      `### Phase 2 Output\n${phase2Text.slice(0, 500)}`
    );
  } else {
    return ctx.escalate(
      "Non-delivery detected: Phase 2 completed but no deliverable files found on disk",
      {
        plannedFiles: uniqueFiles,
        phase1Summary: planText.slice(0, 300),
        phase2Summary: phase2Text.slice(0, 300),
      }
    );
  }
}

