/// <reference path="../../../src/lib/workflow-defs.d.ts" />

/**
 * investigate-thoroughly workflow — Anti-SILENT_FAIL Guard
 *
 * Addresses FM-2.4 SILENT_FAIL: when grep/search returns exit code 1
 * (no matches), the agent concludes "doesn't exist" and stops investigating
 * instead of searching other locations.
 *
 * Two mechanically separate phases prevent premature conclusions:
 *
 * Phase 1 — Gather Evidence: Search EVERY file/location systematically.
 *   For each search, record what was found or explicitly note "not found."
 *   The agent is NOT allowed to draw conclusions or write any report.
 *   This prevents short-circuiting after one empty result.
 *
 * Phase 2 — Analyze & Report: Given the COMPLETE evidence from Phase 1,
 *   write the final report/deliverable. The agent sees ALL search results
 *   before making any judgment, preventing silent-fail conclusions.
 *
 * The structural separation makes it mechanically impossible to skip
 * locations after an empty grep — Phase 1 demands exhaustive search,
 * and Phase 2 only runs after Phase 1 completes.
 *
 * Input: The original investigation/search task string (ctx.task).
 */

export const name: string = "investigate-thoroughly";

export const description: string =
  "Two-phase investigation workflow. Phase 1: exhaustively search every " +
  "relevant location, recording all results including negatives. Phase 2: " +
  "analyze complete evidence and write the report. Prevents SILENT_FAIL " +
  "(FM-2.4) by separating evidence gathering from conclusion drawing.";

// ── Main workflow ──────────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // ═══════════════════════════════════════════════════════════════════
  // PHASE 1: Exhaustive Evidence Gathering
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase1-gather-evidence" });

  const phase1Prompt =
    `## Phase 1: Gather ALL Evidence (DO NOT WRITE REPORT YET)\n\n` +
    `### Task\n${ctx.task}\n\n` +
    `### Instructions — EXHAUSTIVE SEARCH ONLY\n` +
    `Your job in this phase is ONLY to search and record findings. ` +
    `Do NOT write any report or draw final conclusions yet.\n\n` +
    `1. First, list ALL files and directories in the relevant location(s).\n` +
    `2. For EACH file found, search it for the relevant terms/patterns.\n` +
    `3. For each search, record the result using this EXACT format:\n\n` +
    `\`\`\`\n` +
    `EVIDENCE LOG:\n` +
    `- [filename]: FOUND — [what was found, quote relevant lines]\n` +
    `- [filename]: NOT FOUND — [search term] not present in this file\n` +
    `- [filename]: FOUND — [what was found, quote relevant lines]\n` +
    `... (one entry per file)\n` +
    `\`\`\`\n\n` +
    `⚠️ CRITICAL RULES:\n` +
    `- You MUST search EVERY file, not just config files.\n` +
    `- "NOT FOUND" in one file is NOT evidence of absence everywhere.\n` +
    `- grep exit code 1 means "no matches in THIS file" — keep searching others.\n` +
    `- An empty grep result is DATA ("not here"), not a CONCLUSION ("doesn't exist").\n` +
    `- Do NOT stop after the first empty result. Search ALL files.\n` +
    `- Do NOT write any report file. Phase 2 handles that.\n` +
    `- Do NOT call finish() until you have searched every file.\n\n` +
    `Your output must include the EVIDENCE LOG showing results from EVERY file searched.`;

  const phase1 = await ctx.runAgent("tech-lead", phase1Prompt);
  if (phase1.status === "error") {
    return ctx.escalate("Phase 1 (evidence gathering) failed", {
      error: phase1.error,
    });
  }

  const evidenceText = phase1.lastAssistantText ?? "";

  ctx.emit({ type: "step_done", step: "phase1-gather-evidence" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // PHASE 2: Analyze Evidence & Write Report
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase2-analyze-report" });

  const phase2Prompt =
    `## Phase 2: Analyze Evidence & Write Report\n\n` +
    `### Original Task\n${ctx.task}\n\n` +
    `### Complete Evidence from Phase 1\n${evidenceText}\n\n` +
    `### Instructions — WRITE THE REPORT NOW\n` +
    `You have already gathered ALL evidence in Phase 1. The evidence log is above.\n` +
    `Now analyze it and write the deliverable:\n\n` +
    `1. Review ALL evidence entries — both FOUND and NOT FOUND.\n` +
    `2. "NOT FOUND" in some files + "FOUND" in others = the item EXISTS but not everywhere.\n` +
    `3. Write the report/deliverable as specified in the original task.\n` +
    `4. The report must reference evidence from MULTIPLE sources (not just one file).\n` +
    `5. After writing, read the file back to verify it was written correctly.\n\n` +
    `⚠️ Your report MUST mention findings from at least 3 different files.\n` +
    `⚠️ Do NOT conclude "doesn't exist" if ANY file showed a match.\n` +
    `⚠️ If Phase 1 found it in logs/code but not in config, explain WHY ` +
    `(was it removed? deprecated? migrated?).`;

  const phase2 = await ctx.runAgent("tech-lead", phase2Prompt);
  if (phase2.status === "error") {
    return ctx.escalate("Phase 2 (report writing) failed", {
      error: phase2.error,
    });
  }

  ctx.emit({ type: "step_done", step: "phase2-analyze-report" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // Result
  // ═══════════════════════════════════════════════════════════════════
  const phase2Text = phase2.lastAssistantText ?? "";

  return ctx.done(
    `## Investigation Complete (Two-Phase)\n\n` +
    `### Phase 1: Evidence Gathered\n${evidenceText.slice(0, 800)}\n\n` +
    `### Phase 2: Report Written\n${phase2Text.slice(0, 800)}`
  );
}

