    `- Do NOT write any report file. Phase 2 handles that.\n` +
    `- Do NOT call finish() until you have searched every file.\n\n` +
    `Your output must include the EVIDENCE LOG showing results from EVERY file searched.`;

  const phase1 = await ctx.runAgent("tech-lead", phase1Prompt);
  if (phase1.status === "error") {
    return ctx.escalate("Phase 1 (evidence gathering) failed", {
      error: phase1.error,
    });
  }

  const evidenceText = phase1.lastAssistantText ?? "";

  ctx.emit({ type: "step_done", step: "phase1-gather-evidence" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // PHASE 2: Analyze Evidence & Write Report
  // ═══════════════════════════════════════════════════════════════════
  ctx.emit({ type: "step_start", step: "phase2-analyze-report" });

  const phase2Prompt =
    `## Phase 2: Analyze Evidence & Write Report\n\n` +
    `### Original Task\n${ctx.task}\n\n` +
    `### Complete Evidence from Phase 1\n${evidenceText}\n\n` +
    `### Instructions — WRITE THE REPORT NOW\n` +
    `You have already gathered ALL evidence in Phase 1. The evidence log is above.\n` +
    `Now analyze it and write the deliverable:\n\n` +
    `1. Review ALL evidence entries — both FOUND and NOT FOUND.\n` +
    `2. "NOT FOUND" in some files + "FOUND" in others = the item EXISTS but not everywhere.\n` +
    `3. Write the report/deliverable as specified in the original task.\n` +
    `4. The report must reference evidence from MULTIPLE sources (not just one file).\n` +
    `5. After writing, read the file back to verify it was written correctly.\n\n` +
    `⚠️ Your report MUST mention findings from at least 3 different files.\n` +
    `⚠️ Do NOT conclude "doesn't exist" if ANY file showed a match.\n` +
    `⚠️ If Phase 1 found it in logs/code but not in config, explain WHY ` +
    `(was it removed? deprecated? migrated?).`;

  const phase2 = await ctx.runAgent("tech-lead", phase2Prompt);
  if (phase2.status === "error") {
    return ctx.escalate("Phase 2 (report writing) failed", {
      error: phase2.error,
    });
  }

  ctx.emit({ type: "step_done", step: "phase2-analyze-report" } as any);

  // ═══════════════════════════════════════════════════════════════════
  // Result
  // ═══════════════════════════════════════════════════════════════════
  const phase2Text = phase2.lastAssistantText ?? "";

  return ctx.done(
    `## Investigation Complete (Two-Phase)\n\n` +
    `### Phase 1: Evidence Gathered\n${evidenceText.slice(0, 800)}\n\n` +
    `### Phase 2: Report Written\n${phase2Text.slice(0, 800)}`
  );
}
